    assert 3 + 3 > 5 and 3 + 2 <= 5 and 0.1 * 24 * 30 == 72.0 or abs(0.1 * 24 * 30 - 72) < 1e-9
    assert math.ceil(4 * 80 / 50) == 7 and 7e9 * 2 / 1e9 == 14 and 7e9 * 0.5 / 1e9 == 3.5 and 0.5 + 500 / 50 == 10.5


